begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('72000000-0000-0000-0000-000000000001','notes-a@example.test'),('72000000-0000-0000-0000-000000000002','notes-b@example.test');
set local role authenticated;
set local "request.jwt.claim.sub"='72000000-0000-0000-0000-000000000001';
select is(public.read_notes()->'notes','[]'::jsonb,'New libraries have no sample records');
select is(public.save_notes(0,'82000000-0000-0000-0000-000000000001','{"notes":[{"id":"92000000-0000-0000-0000-000000000001","title":"","document":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real text"}]}]},"plainText":"forged","status":"active","pinned":false}],"tags":[{"id":"a2000000-0000-0000-0000-000000000001","path":"ideas","icon":"tag","pinned":false},{"id":"a2000000-0000-0000-0000-000000000002","path":"ideas/writing","icon":"notes","pinned":true}],"links":[{"noteId":"92000000-0000-0000-0000-000000000001","tagId":"a2000000-0000-0000-0000-000000000002"}]}'),1::bigint,'Atomic note and nested tag creation');
select is((select plain_text from public.notes),'Real text','Search text is derived from document');
select is((select parent_id from public.note_tags where path='ideas/writing'),'a2000000-0000-0000-0000-000000000001'::uuid,'Canonical parent is owner scoped');
select throws_ok($$update public.notes set title='bypass'$$,'42501',null,'Direct writes cannot bypass CAS');
select throws_ok($$select public.save_notes(0,gen_random_uuid(),'{"notes":[],"tags":[],"links":[]}')$$,'40001',null,'Stale revision rejected');
select throws_ok($$select public.save_notes(1,gen_random_uuid(),'{"notes":[],"tags":[],"links":[]}')$$,'22023',null,'Active notes cannot disappear without Trash');
select throws_ok($$select public.save_notes(1,gen_random_uuid(),jsonb_build_object('notes',public.read_notes()->'notes','tags','[{"id":"a2000000-0000-0000-0000-000000000003","path":"missing/child","icon":"tag","pinned":false}]'::jsonb,'links','[]'::jsonb))$$,'22023',null,'Invalid graph save rolls back');
select is((public.read_notes()->>'revision')::bigint,1::bigint,'Rejected writes do not advance revision');
select is((select count(*)::integer from public.note_tag_links),1,'Rejected writes preserve joins');
reset role;
select throws_ok($$select muse_private.note_text('{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unsafe","marks":[{"type":"link","attrs":{"href":"javascript:alert(1)"}}]}]}]}')$$,'22023',null,'Unsafe URLs rejected at database boundary');
select throws_ok($$select muse_private.note_text('{"type":"doc","content":[{"type":"image","attrs":{"src":"https://example.test"}}]}')$$,'22023',null,'Unsupported new editor nodes rejected');
set local role authenticated;
set local "request.jwt.claim.sub"='72000000-0000-0000-0000-000000000002';
select is(public.read_notes()->'notes','[]'::jsonb,'Other user cannot read notes');
select is((select count(*)::integer from public.note_tags),0,'Other user cannot read tags');
select is((select count(*)::integer from public.note_tag_links),0,'Other user cannot read associations');
select throws_ok($$select public.save_notes(0,gen_random_uuid(),'{"notes":[{"id":"92000000-0000-0000-0000-000000000001","title":"forged","document":{"type":"doc","content":[{"type":"paragraph"}]},"status":"active","pinned":false}],"tags":[],"links":[]}')$$,'42501',null,'Foreign stable identity cannot be adopted');
select throws_ok($$select public.save_notes(0,gen_random_uuid(),'{"notes":[{"id":"92000000-0000-0000-0000-000000000002","title":"own","document":{"type":"doc","content":[{"type":"paragraph"}]},"status":"active","pinned":false}],"tags":[],"links":[{"noteId":"92000000-0000-0000-0000-000000000002","tagId":"a2000000-0000-0000-0000-000000000001"}]}')$$,'23503',null,'Owner-safe FK rejects a foreign tag association atomically');
set local role anon;
select throws_ok($$select public.read_notes()$$,'42501',null,'Anonymous library access denied');
select throws_ok($$select public.save_notes(0,gen_random_uuid(),'{"notes":[],"tags":[],"links":[]}')$$,'42501',null,'Anonymous command denied');
reset role;
select * from finish();
rollback;
